'use strict';

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const n = input[idx++];
const m = input[idx++];

const a = input.slice(idx, idx + n);
idx += n;
const b = input.slice(idx, idx + n);

const delta = new Array(n);
let baseCost = 0;

for (let i = 0; i < n; i++) {
    delta[i] = a[i] - b[i];
    baseCost += b[i] * m;
}

const totalLength = n * m;
const opensNeeded = totalLength / 2;

function rankAt(maxDelta) {
    const cheap = new Array(n);
    let cheapPerPeriod = 0;

    for (let i = 0; i < n; i++) {
        cheap[i] = delta[i] <= maxDelta ? 1 : 0;
        cheapPerPeriod += cheap[i];
    }

    let minValue = Infinity;
    let prefixCheap = 0;

    for (let r = 0; r < n; r++) {
        const maxQ = r === 0 ? m : m - 1;
        const candidates = [0, 1, maxQ - 1, maxQ];

        for (const q of candidates) {
            if (q < 0 || q > maxQ) continue;

            const position = q * n + r;
            const cheapCount = q * cheapPerPeriod + prefixCheap;
            const value = cheapCount - Math.ceil(position / 2);

            if (value < minValue) minValue = value;
        }

        prefixCheap += cheap[r];
    }

    return opensNeeded + minValue;
}

let previousRank = 0;
let deltaCost = 0;

for (let cost = -9; cost <= 9; cost++) {
    const currentRank = rankAt(cost);
    deltaCost += cost * (currentRank - previousRank);
    previousRank = currentRank;
}

console.log(String(baseCost + deltaCost));

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const n = input[idx++];
const m = input[idx++];

const a = Array(n);
const b = Array(n);

for (let i = 0; i < n; i++) a[i] = input[idx++];
for (let i = 0; i < n; i++) b[i] = input[idx++];

const delta = Array(n);
const values = new Set();

let answer = 0;
for (let i = 0; i < n; i++) {
    delta[i] = a[i] - b[i];
    values.add(delta[i]);
    answer += b[i] * m;
}

const totalLength = n * m;
const requiredOpens = totalLength / 2;
const remainingSteps = requiredOpens - 1;
const period = n / (n % 2 === 0 ? 2 : 1);

const slots = Array(period);
for (let t = 0; t < period; t++) {
    slots[t] = [
        delta[(2 * t + 1) % n],
        delta[(2 * t + 2) % n]
    ];
}

const fullCycles = Math.floor(remainingSteps / period);
const remainder = remainingSteps % period;

function applyRepeatedTransform(x, p, q, times) {
    let resultP = 0;
    let resultQ = -Infinity;
    let baseP = p;
    let baseQ = q;

    while (times > 0) {
        if (times % 2 === 1) {
            resultQ = Math.max(resultQ + baseP, baseQ);
            resultP += baseP;
        }

        baseQ = Math.max(baseQ + baseP, baseQ);
        baseP += baseP;
        times = Math.floor(times / 2);
    }

    return Math.max(x + resultP, resultQ);
}

const sortedValues = [...values].sort((x, y) => x - y);
let previousSelected = 0;

for (const threshold of sortedValues) {
    let cycleArrivals = 0;
    let prefixSum = 0;
    let minimumPrefix = 0;

    for (let t = 0; t < period; t++) {
        let arrivals = 0;
        if (slots[t][0] <= threshold) arrivals++;
        if (slots[t][1] <= threshold) arrivals++;

        cycleArrivals += arrivals;
        prefixSum += arrivals - 1;
        minimumPrefix = Math.min(minimumPrefix, prefixSum);
    }

    const transformP = prefixSum;
    const transformQ = prefixSum - minimumPrefix;

    let queue = applyRepeatedTransform(
        0,
        transformP,
        transformQ,
        fullCycles
    );

    let arrivalsTotal = delta[0] <= threshold ? 1 : 0;
    arrivalsTotal += cycleArrivals * fullCycles;

    for (let t = 0; t < remainder; t++) {
        let arrivals = 0;
        if (slots[t][0] <= threshold) arrivals++;
        if (slots[t][1] <= threshold) arrivals++;

        arrivalsTotal += arrivals;
        queue = Math.max(0, queue + arrivals - 1);
    }

    const selected = arrivalsTotal - queue;
    answer += (selected - previousSelected) * threshold;
    previousSelected = selected;
}

console.log(answer);

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let ptr = 0;

const n = input[ptr++];
const m = input[ptr++];
const a = input.slice(ptr, ptr + n);
ptr += n;
const b = input.slice(ptr, ptr + n);

const weights = Array.from({ length: n }, (_, i) => a[i] - b[i]);
const totalLength = n * m;
const half = totalLength / 2;

function compose(first, second) {
    return {
        A: first.A + second.A,
        B: Math.max(first.B + second.A, second.B)
    };
}

function powerMap(base, exponent) {
    let result = { A: 0, B: -Infinity };

    while (exponent > 0) {
        if (exponent % 2 === 1) {
            result = compose(result, base);
        }
        base = compose(base, base);
        exponent = Math.floor(exponent / 2);
    }

    return result;
}

function applyMap(value, map) {
    return Math.max(value + map.A, map.B);
}

function rankAtThreshold(threshold) {
    let pool = 0;
    let candidates = 0;

    const lastPresent = weights[n - 1] >= threshold ? 1 : 0;
    candidates += lastPresent;
    pool = Math.max(0, pool + lastPresent - 1);

    const steps = half - 1;
    if (steps <= 0) return candidates - pool;

    const period = n / gcd(n, 2);
    const cycleLength = Math.min(period, steps);
    const startK = half - 1;

    let cycleMap = { A: 0, B: -Infinity };
    let cycleCandidates = 0;
    const arrivals = [];

    for (let r = 0; r < cycleLength; r++) {
        const k = startK - r;
        const idx1 = ((2 * k - 1) % n + n) % n;
        const idx2 = (2 * k) % n;
        const x =
            (weights[idx1] >= threshold ? 1 : 0) +
            (weights[idx2] >= threshold ? 1 : 0);

        arrivals.push(x);
        cycleCandidates += x;

        const operation = { A: x - 1, B: 0 };
        cycleMap = compose(cycleMap, operation);
    }

    if (steps < period) {
        for (const x of arrivals) {
            candidates += x;
            pool = Math.max(0, pool + x - 1);
        }
        return candidates - pool;
    }

    const fullCycles = Math.floor(steps / period);
    const remainder = steps % period;

    candidates += fullCycles * cycleCandidates;
    pool = applyMap(pool, powerMap(cycleMap, fullCycles));

    for (let i = 0; i < remainder; i++) {
        const x = arrivals[i];
        candidates += x;
        pool = Math.max(0, pool + x - 1);
    }

    return candidates - pool;
}

function gcd(x, y) {
    while (y !== 0) {
        const t = x % y;
        x = y;
        y = t;
    }
    return x;
}

let maximumSaving = -9 * half;

for (let threshold = -8; threshold <= 9; threshold++) {
    maximumSaving += rankAtThreshold(threshold);
}

const allOpenCost = m * a.reduce((sum, value) => sum + value, 0);
console.log(allOpenCost - maximumSaving);

