const n = input[pos++];
const m = input[pos++];

const a = input.slice(pos, pos + n);
pos += n;
const b = input.slice(pos, pos + n);

const cost = Array.from({ length: n }, (_, i) => b[i] - a[i]);
const period = n % 2 === 0 ? n : 2 * n;
const cycles = n % 2 === 0 ? m : m / 2;

function rankAt(maxCost) {
    let prefix = 0;
    const offsets = new Array(period);

    for (let s = 0; s < period; s++) {
        offsets[s] = Math.floor(s / 2) - prefix;
        if (cost[s % n] <= maxCost) prefix++;
    }

    const drift = period / 2 - prefix;
    let minValue = cycles * drift;

    const cycleIndex = drift < 0 ? cycles - 1 : 0;
    for (const offset of offsets) {
        minValue = Math.min(minValue, cycleIndex * drift + offset);
    }

    return prefix * cycles + minValue;
}

let selectedCost = 0;
let previousRank = 0;

for (let value = -9; value <= 9; value++) {
    const rank = rankAt(value);
    selectedCost += (rank - previousRank) * value;
    previousRank = rank;
}

const baseline = m * a.reduce((sum, value) => sum + value, 0);
