const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const n = input[idx++];
const m = input[idx++];

const a = input.slice(idx, idx + n);
idx += n;
const b = input.slice(idx, idx + n);

const delta = Array.from({ length: n }, (_, i) => a[i] - b[i]);
const totalPairs = n * m / 2;
const period = n / gcd(n, 2);
const buckets = Array(19).fill(0);

let answer = m * b.reduce((sum, x) => sum + x, 0) + delta[0];
const operations = totalPairs - 1;
const fullCycles = Math.floor(operations / period);
const remainder = operations % period;

function gcd(x, y) {
    while (y !== 0) {
        const t = x % y;
        x = y;
        y = t;
    }
    return x;
}

function addCost(cost) {
    const p = cost + 9;
    if (buckets[p] < period) buckets[p]++;
}

function extractMin() {
    for (let i = 0; i < 19; i++) {
        if (buckets[i] > 0) {
            buckets[i]--;
            return i - 9;
        }
    }
    return 0;
}

function runCycle(count) {
    let cost = 0;
    for (let k = 1; k <= count; k++) {
        addCost(delta[(2 * k - 1) % n]);
        addCost(delta[(2 * k) % n]);
        cost += extractMin();
    }
    return cost;
}

let completed = 0;
let selectedCost = 0;
const seen = new Map();

while (completed < fullCycles) {
    const key = buckets.join(',');
    if (seen.has(key)) {
        const [previousCycle, previousCost] = seen.get(key);
        const cycleLength = completed - previousCycle;
        const cycleCost = selectedCost - previousCost;
        const repeat = Math.floor((fullCycles - completed) / cycleLength);

        if (repeat > 0) {
            completed += repeat * cycleLength;
            selectedCost += repeat * cycleCost;
            continue;
        }
    } else {
        seen.set(key, [completed, selectedCost]);
    }

    selectedCost += runCycle(period);
    completed++;
}

selectedCost += runCycle(remainder);
answer += selectedCost;

console.log(answer.toString());
